# structure
# KzgVerifierKey {
#     g1: (x, y),
#     g2: G2Prepared {
#         ell_coeffs: [QuadExtField {...}, ...],
#         infinity: false
#     }
# }

import re
from typing import List, Tuple

def big_endian_chunks_to_int(chunks: List[str]) -> int:
    # Convert from big-endian 64-bit chunks to a single integer
    total = 0
    for chunk in chunks:
        total = (total << 64) + int(chunk.strip())
    return total

def extract_g2_points_big_endian(struct_string: str) -> List[Tuple[int, int]]:
    # Regex pattern to find c0 and c1 BigInt arrays
    pattern = re.compile(
        r"QuadExtField\s*{\s*c0:\s*BigInt\(\[(.*?)\]\),\s*c1:\s*BigInt\(\[(.*?)\]\)\s*}",
        re.DOTALL
    )

    matches = pattern.findall(struct_string)
    g2_points = []

    for c0_str, c1_str in matches:
        c0_chunks = c0_str.split(",")
        c1_chunks = c1_str.split(",")

        c0_int = big_endian_chunks_to_int(c0_chunks)
        c1_int = big_endian_chunks_to_int(c1_chunks)

        g2_points.append((c0_int, c1_int))

    return g2_points

g2_points=extract_g2_points_big_endian(g2)
